const i=[{id:"exocrine-mixed-glands-001",topicId:"exocrine-mixed-glands",question:"Что такое экзокринные железы?",options:["Железы, вырабатывающие только гормоны и ферменты одновременно","Скопления лимфоидной ткани","Железы без протоков, выделяющие гормоны в кровь","Органы, выделяющие секреты через выводные протоки на поверхность тела или в полости органов"],correctIndex:3,explanation:"Экзокринные железы (внешней секреции) выделяют секреты через выводные протоки на поверхность тела или в полости внутренних органов.",difficulty:"easy",tags:["определения"]},{id:"exocrine-mixed-glands-002",topicId:"exocrine-mixed-glands",question:"Какая доля тепла отдаётся организмом путём испарения пота?",options:["Около 5%","Около 50%","Около 90%","Около 20%"],correctIndex:3,explanation:"Кожные железы обеспечивают терморегуляцию: около 20% тепла отдаётся организмом путём испарения пота.",difficulty:"hard",tags:["кожные железы","числовые данные"]},{id:"exocrine-mixed-glands-003",topicId:"exocrine-mixed-glands",question:"От чего предохраняет кожу жировая смазка?",options:["От ожогов","От ультрафиолета","От высыхания и мацерации водой и влажным воздухом","От переломов"],correctIndex:2,explanation:"Жировая смазка предохраняет кожу от высыхания, а также от мацерации (размягчения) водой и влажным воздухом.",difficulty:"medium",tags:["кожные железы"]},{id:"exocrine-mixed-glands-004",topicId:"exocrine-mixed-glands",question:"Что такое мацерация?",options:["Пересыхание кожи","Шелушение кожи","Размягчение кожи водой и влажным воздухом","Покраснение кожи"],correctIndex:2,explanation:"Мацерация — размягчение кожи водой и влажным воздухом.",difficulty:"medium",tags:["терминология"]},{id:"exocrine-mixed-glands-005",topicId:"exocrine-mixed-glands",question:"Какие продукты обмена выводят кожные железы?",options:["Жёлчные кислоты","Углекислый газ","Мочевину, мочевую кислоту, аммиак","Гормоны щитовидной железы"],correctIndex:2,explanation:"Кожные железы обеспечивают выведение продуктов обмена веществ: мочевины, мочевой кислоты, аммиака и др.",difficulty:"medium",tags:["кожные железы"]},{id:"exocrine-mixed-glands-006",topicId:"exocrine-mixed-glands",question:"Производными чего являются потовые железы?",options:["Мышечной ткани","Хрящевой ткани","Костного мозга","Кожного эпителия"],correctIndex:3,explanation:"Потовые железы являются производными кожного эпителия.",difficulty:"medium",tags:["потовые железы"]},{id:"exocrine-mixed-glands-007",topicId:"exocrine-mixed-glands",question:"Где больше всего потовых желёз?",options:["На коже голени","На волосистой части головы","На коже спины и плеч","На коже лица, ладоней, ступней, подмышечных впадин и паховых складок"],correctIndex:3,explanation:"Больше всего потовых желёз на коже лица, ладоней, ступней, подмышечных впадин и паховых складок.",difficulty:"medium",tags:["потовые железы"]},{id:"exocrine-mixed-glands-008",topicId:"exocrine-mixed-glands",question:"Каков состав пота?",options:["80% белков и 20% воды","99% жира и 1% воды","98% воды и 2% органических и неорганических веществ","50% воды и 50% солей"],correctIndex:2,explanation:"Состав пота: 98% воды и 2% органических и неорганических веществ.",difficulty:"medium",tags:["потовые железы","числовые данные"]},{id:"exocrine-mixed-glands-009",topicId:"exocrine-mixed-glands",question:"Какая соль выделяется с потом, по данным лекции?",options:["Хлорид натрия","Фосфат железа","Карбонат кальция","Сульфат магния"],correctIndex:0,explanation:"Функции потовых желёз включают выделение солей (хлорида натрия и др.).",difficulty:"medium",tags:["потовые железы"]},{id:"exocrine-mixed-glands-010",topicId:"exocrine-mixed-glands",question:"Что НЕ относится к функциям потовых желёз?",options:["Выделение продуктов белкового обмена","Выделение специфических пахучих веществ","Выработка кожного сала","Терморегуляция"],correctIndex:2,explanation:"Функции потовых желёз: терморегуляция, выделение продуктов белкового обмена, солей и пахучих веществ. Кожное сало вырабатывают сальные железы.",difficulty:"medium",tags:["потовые железы"]},{id:"exocrine-mixed-glands-011",topicId:"exocrine-mixed-glands",question:"Когда сальные железы достигают наибольшего развития?",options:["В период новорождённости","Во время полового созревания","Во время беременности","В пожилом возрасте"],correctIndex:1,explanation:"Сальные железы достигают наибольшего развития во время полового созревания.",difficulty:"medium",tags:["сальные железы"]},{id:"exocrine-mixed-glands-012",topicId:"exocrine-mixed-glands",question:"С чем связаны выводные протоки сальных желёз?",options:["С кровеносными сосудами","С лимфатическими протоками","С потовыми железами","С волосами"],correctIndex:3,explanation:"Выводные протоки сальных желёз связаны с волосами.",difficulty:"medium",tags:["сальные железы"]},{id:"exocrine-mixed-glands-013",topicId:"exocrine-mixed-glands",question:"Сколько сальных желёз можно встретить около одного корня волоса?",options:["До трёх","Около двадцати","Только одну","До десяти"],correctIndex:0,explanation:"Около одного корня волоса можно встретить до трёх сальных желёз.",difficulty:"hard",tags:["сальные железы","числовые данные"]},{id:"exocrine-mixed-glands-014",topicId:"exocrine-mixed-glands",question:"Где отсутствуют сальные железы?",options:["На ладонях и подошвах","На лице","На голове","На верхней части спины"],correctIndex:0,explanation:"Больше всего сальных желёз на голове, лице и верхней части спины; на ладонях и подошвах они отсутствуют.",difficulty:"medium",tags:["сальные железы"]},{id:"exocrine-mixed-glands-015",topicId:"exocrine-mixed-glands",question:"Как называется секрет сальных желёз?",options:["Лизоцим","Ушная сера","Пот","Кожное сало"],correctIndex:3,explanation:"Секрет сальных желёз — кожное сало.",difficulty:"easy",tags:["сальные железы"]},{id:"exocrine-mixed-glands-016",topicId:"exocrine-mixed-glands",question:"Какую функцию выполняет кожное сало?",options:["Смягчает кожу и волосы и препятствует развитию микроорганизмов","Выводит мочевину","Охлаждает тело за счёт испарения","Переваривает углеводы"],correctIndex:0,explanation:"Функции кожного сала: смягчает кожу и волосы, придаёт эластичность, облегчает трение, препятствует развитию микроорганизмов.",difficulty:"medium",tags:["сальные железы"]},{id:"exocrine-mixed-glands-017",topicId:"exocrine-mixed-glands",question:"На какой неделе развития закладываются молочные железы у зародыша?",options:["На 20-й неделе","На 1–2-й неделе","На 36-й неделе","На 6–7-й неделе"],correctIndex:3,explanation:"Молочные железы закладываются у зародыша на 6–7-й неделе в виде двух уплотнений эпидермиса («молочных линий»).",difficulty:"hard",tags:["молочные железы","развитие"]},{id:"exocrine-mixed-glands-018",topicId:"exocrine-mixed-glands",question:"Как называются уплотнения эпидермиса, из которых формируются молочные железы?",options:["Молочные линии","Остеоны","Эпифизарные пластинки","Ацинусы"],correctIndex:0,explanation:"Молочные железы закладываются в виде двух уплотнений эпидермиса — «молочных линий», тянущихся вдоль туловища.",difficulty:"hard",tags:["молочные железы","развитие"]},{id:"exocrine-mixed-glands-019",topicId:"exocrine-mixed-glands",question:"Когда молочная железа достигает окончательного развития?",options:["Только при беременности в период лактации","В период полового созревания","После менопаузы","В детском возрасте"],correctIndex:0,explanation:"Молочная железа достигает окончательного развития только при беременности в период лактации.",difficulty:"medium",tags:["молочные железы"]},{id:"exocrine-mixed-glands-020",topicId:"exocrine-mixed-glands",question:"Какой углевод входит в состав молока?",options:["Глюкоза","Крахмал","Сахароза","Лактоза"],correctIndex:3,explanation:"Молоко содержит жиры, белки (казеин и др.), углеводы (лактозу), соли и иммуноглобулины.",difficulty:"easy",tags:["молоко"]},{id:"exocrine-mixed-glands-021",topicId:"exocrine-mixed-glands",question:"Какой белок назван в лекции в составе молока?",options:["Миоглобин","Коллаген","Казеин","Альбумин"],correctIndex:2,explanation:"В состав молока входят белки — казеин и др.",difficulty:"medium",tags:["молоко"]},{id:"exocrine-mixed-glands-022",topicId:"exocrine-mixed-glands",question:"Какой гормон стимулирует лактоциты к биосинтезу молока?",options:["Пролактин","Тироксин","Окситоцин","Прогестерон"],correctIndex:0,explanation:"Пролактин (гормон гипофиза) стимулирует железистые клетки альвеол (лактоциты) к биосинтезу молока.",difficulty:"easy",tags:["молочные железы","гормоны"]},{id:"exocrine-mixed-glands-023",topicId:"exocrine-mixed-glands",question:"Какой гормон стимулирует выведение молока из млечных протоков?",options:["Пролактин","Эстроген","Кальцитонин","Окситоцин"],correctIndex:3,explanation:"Окситоцин стимулирует выведение молока из млечных протоков во время лактации.",difficulty:"easy",tags:["молочные железы","гормоны"]},{id:"exocrine-mixed-glands-024",topicId:"exocrine-mixed-glands",question:"Как называются железистые клетки альвеол молочной железы?",options:["Лактоциты","Нефроциты","Остеоциты","Гепатоциты"],correctIndex:0,explanation:"Железистые клетки альвеол молочной железы — лактоциты.",difficulty:"medium",tags:["молочные железы"]},{id:"exocrine-mixed-glands-025",topicId:"exocrine-mixed-glands",question:"Какие железы относятся к пищеварительным?",options:["Слюнные, желудочные, кишечные, поджелудочная железа и печень","Гипофиз и эпифиз","Щитовидная и паращитовидные","Потовые и сальные"],correctIndex:0,explanation:"К пищеварительным железам относятся слюнные, желудочные, кишечные, поджелудочная железа и печень.",difficulty:"easy",tags:["пищеварительные железы"]},{id:"exocrine-mixed-glands-026",topicId:"exocrine-mixed-glands",question:"Сколько пар крупных слюнных желёз у человека?",options:["Одна","Четыре","Две","Три"],correctIndex:3,explanation:"Выделяют три пары крупных слюнных желёз и множество мелких на языке и нёбе.",difficulty:"easy",tags:["слюнные железы"]},{id:"exocrine-mixed-glands-027",topicId:"exocrine-mixed-glands",question:"Где расположены околоушные слюнные железы?",options:["На нёбе","Ниже уровня уха","Под краями языка","Возле углов нижней челюсти"],correctIndex:1,explanation:"Околоушные слюнные железы расположены ниже уровня уха.",difficulty:"medium",tags:["слюнные железы"]},{id:"exocrine-mixed-glands-028",topicId:"exocrine-mixed-glands",question:"Где расположены подчелюстные слюнные железы?",options:["Под краями языка","Ниже уровня уха","Возле углов нижней челюсти","В толще щёк"],correctIndex:2,explanation:"Подчелюстные слюнные железы расположены возле углов нижней челюсти; подъязычные — под краями языка.",difficulty:"medium",tags:["слюнные железы"]},{id:"exocrine-mixed-glands-029",topicId:"exocrine-mixed-glands",question:"Сколько воды содержится в слюне?",options:["50%","99%","75%","80%"],correctIndex:1,explanation:"Состав слюны: 99% — вода, ферменты (амилазы), лизоцим.",difficulty:"medium",tags:["слюнные железы","числовые данные"]},{id:"exocrine-mixed-glands-030",topicId:"exocrine-mixed-glands",question:"Какие ферменты слюны обеспечивают первичное переваривание углеводов?",options:["Амилазы","Пепсин","Трипсин","Липазы"],correctIndex:0,explanation:"Ферменты слюны (амилазы) обеспечивают первичное переваривание углеводов.",difficulty:"easy",tags:["слюнные железы"]},{id:"exocrine-mixed-glands-031",topicId:"exocrine-mixed-glands",question:"Какое вещество слюны обладает антибактериальными и ранозаживляющими свойствами?",options:["Амилаза","Казеин","Лактоза","Лизоцим"],correctIndex:3,explanation:"Лизоцим слюны обладает антибактериальными и ранозаживляющими свойствами.",difficulty:"medium",tags:["слюнные железы"]},{id:"exocrine-mixed-glands-032",topicId:"exocrine-mixed-glands",question:"Что такое железы смешанной секреции?",options:["Железы, выделяющие только пот","Железы, не имеющие секреторной функции","Органы, совмещающие функции внешней и внутренней секреции","Железы, выделяющие только гормоны"],correctIndex:2,explanation:"Железы смешанной секреции совмещают функции внешней (экзокринной) и внутренней (эндокринной) секреции.",difficulty:"easy",tags:["смешанные железы"]},{id:"exocrine-mixed-glands-033",topicId:"exocrine-mixed-glands",question:"Какие органы относятся к основным железам смешанной секреции?",options:["Слюнные и потовые железы","Поджелудочная железа и половые железы","Печень и селезёнка","Щитовидная железа и надпочечники"],correctIndex:1,explanation:"К основным железам смешанной секреции относятся поджелудочная железа и половые железы (семенники и яичники).",difficulty:"medium",tags:["смешанные железы"]},{id:"exocrine-mixed-glands-034",topicId:"exocrine-mixed-glands",question:"Какие структуры поджелудочной железы выделяют инсулин и глюкагон?",options:["Островки Лангерганса","Ацинусы","Вирсунгов проток","Лактоциты"],correctIndex:0,explanation:"Внутренняя секреция поджелудочной железы: островки Лангерганса выделяют инсулин и глюкагон в кровь.",difficulty:"medium",tags:["смешанные железы","поджелудочная железа"]},{id:"exocrine-mixed-glands-035",topicId:"exocrine-mixed-glands",question:"Как глюкагон влияет на уровень глюкозы в крови?",options:["Сначала снижает, затем повышает","Не влияет на него","Снижает его","Повышает его"],correctIndex:3,explanation:"Инсулин снижает уровень глюкозы, глюкагон — повышает.",difficulty:"easy",tags:["смешанные железы","поджелудочная железа"]},{id:"exocrine-mixed-glands-036",topicId:"exocrine-mixed-glands",question:"В чём заключается внешняя секреция половых желёз?",options:["В выработке половых гормонов","В выработке инсулина","В образовании и выделении половых клеток","В выделении пота"],correctIndex:2,explanation:"Внешняя секреция гонад — образование и выделение половых клеток (сперматозоидов и яйцеклеток).",difficulty:"hard",tags:["смешанные железы","половые железы"]},{id:"exocrine-mixed-glands-037",topicId:"exocrine-mixed-glands",question:"Какой половой гормон вырабатывается у мужчин?",options:["Эстроген","Прогестерон","Пролактин","Тестостерон"],correctIndex:3,explanation:"Внутренняя секреция гонад: тестостерон у мужчин, эстрогены и прогестерон у женщин.",difficulty:"easy",tags:["смешанные железы","половые железы"]},{id:"exocrine-mixed-glands-038",topicId:"exocrine-mixed-glands",question:"За что отвечают половые гормоны?",options:["За кроветворение","За формирование вторичных половых признаков, мышечную массу и половую функцию","За терморегуляцию","Только за пищеварение"],correctIndex:1,explanation:"Половые гормоны отвечают за формирование вторичных половых признаков, развитие мышечной массы, половую функцию, либидо и влияют на обмен веществ.",difficulty:"medium",tags:["смешанные железы","половые железы"]}];export{i as default};
